baseCss:
.aha-article{
  container:aha-article / inline-size;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-article *{box-sizing:border-box}
:where(.aha-article) h1,:where(.aha-article) h2,:where(.aha-article) h3,:where(.aha-article) h4,:where(.aha-article) p,:where(.aha-article) ul,:where(.aha-article) ol,:where(.aha-article) figure,:where(.aha-article) blockquote{margin:0;padding:0;border:0}
.aha-article__inner{
  --aha-web-gutter:var(--aha-space-64);
  display:grid;
  grid-template-columns:minmax(0,384px) minmax(0,720px);
  grid-template-areas:"header header" "aside body" ". footer";
  column-gap:var(--aha-space-64);
  justify-content:center;
  width:100%;max-width:calc(1280px + 2 * var(--aha-web-gutter));
  margin:0 auto;
  padding:var(--aha-section-space-block) var(--aha-web-gutter);
}
.aha-article__inner--part{display:block;max-width:calc(720px + 2 * var(--aha-web-gutter))}
.aha-article__inner>.aha-article-header{grid-area:header;margin-bottom:var(--aha-section-space-header)}
.aha-article__aside{
  grid-area:aside;align-self:start;
  position:sticky;top:var(--aha-space-96);
  display:flex;flex-direction:column;gap:var(--aha-section-space-group);
  max-height:calc(100vh - var(--aha-space-96));overflow-y:auto;
}
.aha-article__body{grid-area:body;min-width:0}
.aha-article__footer{
  grid-area:footer;
  display:flex;flex-wrap:wrap;align-items:center;gap:var(--aha-space-12);
  margin-top:var(--aha-section-space-group);padding-top:var(--aha-section-space-group);
  border-top:1px solid var(--aha-border-default);
}
.aha-article__tags-label{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-article__tag-list{display:flex;flex-wrap:wrap;gap:var(--aha-space-8);list-style:none}

.aha-article-header{display:flex;flex-direction:column;align-items:center;gap:var(--aha-section-space-header)}
.aha-article-header__text{display:flex;flex-direction:column;align-items:center;gap:var(--aha-space-24);width:100%;max-width:720px;text-align:center}
.aha-article-header__title{
  display:block;
  font-size:var(--aha-size-h1);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
}
.aha-article-header__meta{
  display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:var(--aha-space-8);
  font-size:var(--aha-size-default);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-article-header__categories{display:inline-flex;flex-wrap:wrap;gap:var(--aha-space-8)}
.aha-article-header__byline{display:inline-flex;align-items:center;gap:var(--aha-space-8)}
.aha-article-header__facts{display:inline-flex;align-items:center;gap:var(--aha-space-8)}
.aha-article-header__author{color:var(--aha-text-default);font-weight:var(--aha-weight-semibold);text-decoration:none;border-radius:var(--aha-radius-xs);transition:color var(--aha-motion-fast) var(--aha-ease-out)}
@media (hover:hover){
  .aha-article-header__author:hover{color:var(--aha-text-link-hover);text-decoration:underline}
}
.aha-article-header__author:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-article-header__image{display:block;width:100%;height:auto;border-radius:var(--aha-radius-marketing)}

.aha-article-tag{display:inline-flex;border-radius:var(--aha-radius-xs);text-decoration:none}
.aha-article-tag:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}

.aha-text-link,.aha-article-prose a{
  color:var(--aha-text-link);
  font-weight:var(--aha-weight-regular);
  text-decoration:underline;
  border-radius:var(--aha-radius-xs);
  transition:color var(--aha-motion-fast) var(--aha-ease-out);
}
.aha-text-link:hover,.aha-article-prose a:hover{color:var(--aha-text-link-hover)}
.aha-text-link:active,.aha-article-prose a:active{color:var(--aha-color-primary-active)}
.aha-text-link:focus-visible,.aha-article-prose a:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-article-prose :is(blockquote,.aha-article-callout) a,.aha-article-prose :is(blockquote,.aha-article-callout) a:hover{color:var(--aha-text-default)}

.aha-article-prose{
  font-size:var(--aha-size-l);
  font-weight:var(--aha-weight-regular);
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-default);
  overflow-wrap:break-word;
}
.aha-article-prose>:first-child{margin-top:0}
.aha-article-prose :is(h2,h3,h4){font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default);scroll-margin-top:var(--aha-space-96)}
.aha-article-prose h2{font-size:var(--aha-size-h3);margin:var(--aha-space-48) 0 var(--aha-space-16)}
.aha-article-prose h3{font-size:var(--aha-size-h4);margin:var(--aha-space-32) 0 var(--aha-space-12)}
.aha-article-prose h4{font-size:var(--aha-size-xl);margin:var(--aha-space-24) 0 var(--aha-space-8)}
.aha-article-prose :is(p,ul,ol){margin:0 0 var(--aha-space-16)}
.aha-article-prose :is(ul,ol){padding-inline-start:var(--aha-space-24)}
.aha-article-prose li+li,.aha-article-prose li>:is(ul,ol){margin-top:var(--aha-space-8)}
.aha-article-prose li>:is(ul,ol){margin-bottom:0}
.aha-article-prose strong{font-weight:var(--aha-weight-semibold)}
.aha-article-prose blockquote{
  margin:var(--aha-space-24) 0;padding:var(--aha-space-24);
  border:0;border-radius:var(--aha-radius-default);
  background:var(--aha-bg-accent);
}
.aha-article-prose blockquote>:last-child{margin-bottom:0}
.aha-article-prose cite{display:block;margin-top:var(--aha-space-8);font-size:var(--aha-size-default);font-style:normal;color:var(--aha-text-secondary)}
.aha-article-prose figure{margin:var(--aha-space-24) 0}
.aha-article-prose img{display:block;max-width:100%;height:auto;border-radius:var(--aha-radius-default)}
.aha-article-prose figure>img{width:100%}
.aha-article-prose figcaption{margin-top:var(--aha-space-8);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary);text-align:center}
.aha-article-prose code{
  padding:var(--aha-space-2) var(--aha-space-4);
  border-radius:var(--aha-radius-xs);
  background:var(--aha-bg-container-secondary);
  font-family:var(--aha-font-mono);font-size:var(--aha-size-default);
}
.aha-article-prose pre{
  margin:var(--aha-space-24) 0;padding:var(--aha-space-16);white-space:pre-wrap;overflow-wrap:anywhere;
  border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-default);
  background:var(--aha-white);
  font-family:var(--aha-font-mono);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);
}
.aha-article-prose pre code{padding:0;background:none}
.aha-article-prose hr{margin:var(--aha-space-32) 0;border:0;border-top:1px solid var(--aha-border-default)}
.aha-article-prose__table{margin:var(--aha-space-24) 0;overflow-x:auto;border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-default)}
.aha-article-prose table{width:100%;border-collapse:collapse;font-size:var(--aha-size-default);line-height:var(--aha-line-height-body)}
.aha-article-prose :is(th,td){padding:var(--aha-space-12) var(--aha-space-16);border-bottom:1px solid var(--aha-border-default);text-align:start;vertical-align:top}
.aha-article-prose th{font-weight:var(--aha-weight-semibold)}
.aha-article-prose thead th{border-bottom-color:var(--aha-border-strong)}
.aha-article-prose tbody tr:last-child>*{border-bottom:0}
.aha-article-callout{
  margin:var(--aha-space-32) 0;padding:var(--aha-space-32) var(--aha-space-24);
  border-radius:var(--aha-radius-marketing);
  background:var(--aha-bg-accent);
}
.aha-article-prose .aha-article-callout>h3{margin-top:0}
.aha-article-callout>aha-button{margin-top:var(--aha-space-8)}

.aha-article-toc__toggle{display:none}
.aha-article-toc__title{
  display:block;margin-bottom:var(--aha-space-12);
  font-size:var(--aha-size-l);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-text-default);
}
.aha-article-toc__list,.aha-article-toc__list ol{margin:0;padding:0;list-style:none}
.aha-article-toc__link{
  display:block;padding:var(--aha-space-6) var(--aha-space-12);
  border-inline-start:var(--aha-space-2) solid var(--aha-border-default);
  color:var(--aha-text-secondary);
  font-size:var(--aha-size-default);
  line-height:var(--aha-line-height-body);
  text-decoration:none;
  transition:color var(--aha-motion-fast) var(--aha-ease-out),border-color var(--aha-motion-fast) var(--aha-ease-out);
}
.aha-article-toc__list ol .aha-article-toc__link{padding-inline-start:var(--aha-space-24)}
@media (hover:hover){
  .aha-article-toc__link:hover{color:var(--aha-text-link-hover)}
}
.aha-article-toc__link:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:calc(-1 * var(--aha-space-2));border-radius:var(--aha-radius-xs)}
.aha-article-toc__link[aria-current]{color:var(--aha-text-link);border-inline-start-color:var(--aha-color-primary)}

.aha-article-share{display:flex;flex-wrap:wrap;align-items:center;gap:var(--aha-space-8)}
.aha-article-share__label{margin-inline-end:var(--aha-space-4);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-article-share__list{display:flex;gap:var(--aha-space-8);list-style:none}
.aha-article-share__status{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}

@media (prefers-reduced-motion:reduce){
  .aha-article-header__author,.aha-text-link,.aha-article-prose a,.aha-article-toc__link{transition:none}
}
@container aha-article (max-width:991px){
  .aha-article__inner{grid-template-columns:minmax(0,720px);grid-template-areas:"header" "aside" "body" "footer"}
  .aha-article__aside{position:static;max-height:none;overflow:visible;margin-bottom:var(--aha-section-space-group)}
  .aha-article-header__title{font-size:var(--aha-size-h2)}
  .aha-article-toc__toggle{display:block}
  .aha-article-toc__title{display:none}
  .aha-article-toc__list{display:none;margin-top:var(--aha-space-12)}
  .aha-article-toc--open .aha-article-toc__list{display:block}
}
@container aha-article (max-width:767px){
  .aha-article__inner{--aha-web-gutter:var(--aha-space-24)}
  .aha-article-prose h2{font-size:var(--aha-size-h4);margin-top:var(--aha-space-32)}
  .aha-article-prose h3{font-size:var(--aha-size-xl)}
  .aha-article-prose h4{font-size:var(--aha-size-l)}
}
@container aha-article (max-width:479px){
  .aha-article__inner{--aha-web-gutter:var(--aha-space-16)}
  .aha-article-header__title{font-size:var(--aha-size-h3)}
  .aha-article-header__facts{flex-basis:100%;justify-content:center}
  .aha-article-header__sep{display:none}
  .aha-article-callout{padding:var(--aha-space-24) var(--aha-space-16)}
}
